import{_ as s,o as t,c as e,a6 as n}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"ビルドとは何か — コンパイラとビルドシステムの違い","description":"","frontmatter":{"title":"ビルドとは何か — コンパイラとビルドシステムの違い","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"コンパイラ(g++, cl.exe): 1つの翻訳単位を機械語にする「職人」 ビルドシステム(CMake+Make/Ninja, MSBuild): 「何を・どの順で・どの設定で職人に依頼し、リンクまで完走させるか」を管理する「現場監督」"}},"headers":[],"relativePath":"tools/build/what-is-build.md","filePath":"tools/build/what-is-build.md"}'),l={name:"tools/build/what-is-build.md"};function i(d,a,o,p,r,c){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="ビルドとは何か-—-コンパイラとビルドシステムの違い" tabindex="-1">ビルドとは何か — コンパイラとビルドシステムの違い <a class="header-anchor" href="#ビルドとは何か-—-コンパイラとビルドシステムの違い" aria-label="Permalink to &quot;ビルドとは何か — コンパイラとビルドシステムの違い&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><ul><li><strong>コンパイラ</strong>(g++, cl.exe): 1つの翻訳単位を機械語にする「職人」</li><li><strong>ビルドシステム</strong>(CMake+Make/Ninja, MSBuild): 「<strong>何を・どの順で・どの設定で</strong>職人に依頼し、リンクまで完走させるか」を管理する「現場監督」</li></ul><p><code>g++ main.cpp</code> で済むのは1ファイルの時だけ。実際のゲームは数百〜数万ファイル+ライブラリ+プラットフォーム別設定であり、その管理が「ビルド」という仕事です。</p><h2 id="ビルドの全体像-監督の仕事" tabindex="-1">ビルドの全体像(監督の仕事) <a class="header-anchor" href="#ビルドの全体像-監督の仕事" aria-label="Permalink to &quot;ビルドの全体像(監督の仕事)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ソース群 ──┐</span></span>
<span class="line"><span>           ├─ ①どの.cppをコンパイルするか(ソースリスト)</span></span>
<span class="line"><span>設定 ──────┼─ ②どんなフラグで(-O2? -std=c++20? どのdefine?)</span></span>
<span class="line"><span>           ├─ ③どの順で(依存関係: 変更されたものと、その影響先だけ再コンパイル)</span></span>
<span class="line"><span>ライブラリ ─┼─ ④何とリンクするか(-lfmod、パスの解決)</span></span>
<span class="line"><span>           └─ ⑤成果物をどこへ(bin/game.exe、シンボルファイル)</span></span></code></pre></div><ul><li>③が<strong>インクリメンタルビルド</strong>の核心: ファイルのタイムスタンプ+ヘッダー依存関係(コンパイラが出す依存情報)から「再コンパイルすべき最小集合」を計算する(→ <a href="/study/tools/build/build-speed.html">ビルド速度</a>)</li><li>Unityで「保存すると勝手にコンパイルされる」のは、Unityエディタがこの監督業を全部やっているから。C++では自分で(またはUEのUBTのようなツールが)監督をやる必要がある</li></ul><h2 id="手動でやってみる-1回だけの体験として" tabindex="-1">手動でやってみる(1回だけの体験として) <a class="header-anchor" href="#手動でやってみる-1回だけの体験として" aria-label="Permalink to &quot;手動でやってみる(1回だけの体験として)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++ -std=c++2a -c enemy.cpp -o enemy.o      # ①翻訳単位ごとにコンパイル</span></span>
<span class="line"><span>g++ -std=c++2a -c main.cpp -o main.o</span></span>
<span class="line"><span>g++ main.o enemy.o -o game.exe               # ②リンク</span></span>
<span class="line"><span># ファイルが増えるたび・依存が増えるたび、手動管理は破綻する → ビルドシステムへ</span></span></code></pre></div><h2 id="道具の階層-混乱しやすいので整理" tabindex="-1">道具の階層(混乱しやすいので整理) <a class="header-anchor" href="#道具の階層-混乱しやすいので整理" aria-label="Permalink to &quot;道具の階層(混乱しやすいので整理)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[メタビルドシステム] CMake, Premake   … ビルド設定の「設計図」を書く(プラットフォーム非依存)</span></span>
<span class="line"><span>        ↓ 生成</span></span>
<span class="line"><span>[ビルドシステム]     Make, Ninja, MSBuild(.vcxproj), Xcode … 依存解決と実行</span></span>
<span class="line"><span>        ↓ 呼び出し</span></span>
<span class="line"><span>[コンパイラ/リンカ]  g++, clang++, cl.exe / ld, link.exe</span></span></code></pre></div><ul><li>CMakeは<strong>ビルドしない</strong>(NinjaやVSプロジェクトを生成する)。この区別が分かるとエラーの切り分け(CMakeの設定ミスか、コンパイルエラーか)ができる</li><li>UEのUBT(Unreal Build Tool)はこの階層を自前で持つ独自の監督(→ <a href="/study/game/unreal/build-system-ubt.html">第10部</a>)</li></ul><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><table tabindex="0"><thead><tr><th>C#/Unity</th><th>C++</th></tr></thead><tbody><tr><td>.csproj / MSBuild(Riderが隠している)</td><td>CMakeLists.txt / vcxproj</td></tr><tr><td>Unityのスクリプトコンパイル(自動)</td><td>ビルドシステムの実行(明示的)</td></tr><tr><td>アセンブリ参照(GUIで追加)</td><td>ライブラリのリンク設定(パス・名前・順序)</td></tr><tr><td>Library/のキャッシュ</td><td>ビルドディレクトリの.oとキャッシュ</td></tr><tr><td>「Reimport All」</td><td>クリーンビルド</td></tr></tbody></table><p>C#で「ビルドはIDEが勝手にやるもの」だった感覚に対し、C++は**ビルドが構成物(コードと同じくレビュー対象)**という文化の違いがあります。</p><h2 id="ゲーム開発での現実" tabindex="-1">ゲーム開発での現実 <a class="header-anchor" href="#ゲーム開発での現実" aria-label="Permalink to &quot;ゲーム開発での現実&quot;">​</a></h2><ul><li>ゲームは<strong>マルチプラットフォームビルド</strong>(Windows/PS/Switch/…)が前提になりやすく、設定の分岐管理がビルドシステムの主戦場</li><li>アセットビルド(テクスチャ圧縮等)もビルドの一部として同じ依存グラフ思考で管理される(ビルドパイプライン)</li><li>「ビルドを壊した」が全員を止める——CI(→ <a href="/study/tools/build/debugging-and-analysis.html">品質ツール</a>)が門番になる</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>コンパイラとビルドシステムの役割分担を「職人と監督」以外の言葉で説明できますか。</li><li>インクリメンタルビルドは何の情報を使って「再コンパイル最小集合」を決めますか。</li><li>CMakeが「ビルドしない」とはどういう意味ですか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/tools/build/samples/tu-demo.html">samples/tu_demo/</a> を、(a) 手動のg++コマンド列でビルド、(b) 1ファイルだけ変更して全再コンパイルの無駄を体感、(c) 次ページのCMake化で(b)が解決されることを確認する準備をしてください。</p><hr><p>前: <a href="/study/tools/build/">カテゴリ目次</a> | 次: <a href="/study/tools/build/compilers.html">三大コンパイラ</a></p>`,23)])])}const b=s(l,[["render",i]]);export{u as __pageData,b as default};
